import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

const COLS = `vat_form_id AS "vatFormId",
  tax_period_start AS "taxPeriodStart",
  tax_period_end AS "taxPeriodEnd",
  form_type AS "formType",
  input_values AS "inputValues",
  confirmed AS "confirmed"`;

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function isPlainObject(v: unknown): boolean {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

@Controller('api/v1')
export class FnSfr01006Controller {
  @Get('/vat-forms')
  async listVatForms(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const start = text(q['taxPeriodStart']);
    const end = text(q['taxPeriodEnd']);
    const formType = text(q['formType']);
    if (!start || !end || !formType || !DATE_RE.test(start) || !DATE_RE.test(end)) {
      throw new ApiError(422, 'VAT_PERIOD_OR_FORM_TYPE_REQUIRED', '과세기간과 서식 구분을 모두 입력해 주세요.');
    }
    const pageRaw = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const params = {
        start,
        end,
        formType,
        limit: size,
        offset: page * size,
      };
      const where = `tax_period_start = CAST(:start AS date)
        AND tax_period_end = CAST(:end AS date)
        AND form_type = :formType`;
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM vat_form WHERE ${where}`,
        params,
      );
      const items = await db.query(
        `SELECT ${COLS} FROM vat_form WHERE ${where} ORDER BY vat_form_id LIMIT :limit OFFSET :offset`,
        params,
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/vat-forms')
  @HttpCode(200)
  async createVatForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const start = text(data['taxPeriodStart']);
    const end = text(data['taxPeriodEnd']);
    const formType = text(data['formType']);
    if (!start || !end || !formType) {
      throw new ApiError(422, 'INVALID_VAT_FORM_INPUT', '과세기간과 서식 구분을 모두 입력해 주세요.');
    }
    if (!DATE_RE.test(start) || !DATE_RE.test(end) || end < start) {
      throw new ApiError(422, 'INVALID_VAT_FORM_INPUT', '과세기간 형식이 올바르지 않습니다. 종료일은 시작일 이후여야 합니다.');
    }
    if (formType.length > 100) {
      throw new ApiError(422, 'INVALID_VAT_FORM_INPUT', '서식 구분은 100자 이내여야 합니다.');
    }
    const rawInput = data['inputValues'];
    if (rawInput !== undefined && rawInput !== null && !isPlainObject(rawInput)) {
      throw new ApiError(422, 'INVALID_VAT_FORM_INPUT', '서식 입력값은 객체 형식이어야 합니다.');
    }
    const inputJson = rawInput === undefined || rawInput === null ? null : JSON.stringify(rawInput);
    return transaction(async (db) => {
      const params = { start, end, formType, inputJson };
      const existing = await db.query(
        `SELECT vat_form_id AS "vatFormId", confirmed AS "confirmed"
         FROM vat_form
         WHERE tax_period_start = CAST(:start AS date)
           AND tax_period_end = CAST(:end AS date)
           AND form_type = :formType`,
        params,
      );
      if (existing.length > 0) {
        if (existing[0]['confirmed'] === true) {
          throw new ApiError(409, 'VAT_PERIOD_CONFIRMED', '확정·마감된 과세기간의 서식입니다. 정해진 취소 절차가 필요합니다.');
        }
        // 가정: 같은 과세기간·서식 구분의 미확정 서식이 있으면 새로 만들지 않고 입력값을 덮어써 저장한다.
        const updated = await db.query(
          `UPDATE vat_form
           SET input_values = CAST(:inputJson AS jsonb), updated_at = now()
           WHERE vat_form_id = CAST(:id AS bigint)
           RETURNING ${COLS}`,
          { inputJson, id: String(existing[0]['vatFormId']) },
        );
        return updated[0];
      }
      // 가정: 등록 시 확정 여부는 false로 시작한다.
      const rows = await db.query(
        `INSERT INTO vat_form (tax_period_start, tax_period_end, form_type, input_values, confirmed, created_at, updated_at)
         VALUES (CAST(:start AS date), CAST(:end AS date), :formType, CAST(:inputJson AS jsonb), false, now(), now())
         RETURNING ${COLS}`,
        params,
      );
      return rows[0];
    });
  }

  @Patch('/vat-forms/:vatFormId')
  async updateVatForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['vatFormId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '서식 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const rawInput = data['inputValues'];
    if (!isPlainObject(rawInput)) {
      throw new ApiError(422, 'INVALID_VAT_FORM_INPUT', '서식 입력값은 객체 형식이어야 합니다.');
    }
    const inputJson = JSON.stringify(rawInput);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT confirmed AS "confirmed" FROM vat_form WHERE vat_form_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'VAT_FORM_NOT_FOUND', '대상 서식이 없습니다.');
      }
      if (found[0]['confirmed'] === true) {
        throw new ApiError(409, 'VAT_PERIOD_CONFIRMED', '확정·마감된 과세기간의 서식입니다. 정해진 취소 절차가 필요합니다.');
      }
      const rows = await db.query(
        `UPDATE vat_form
         SET input_values = CAST(:inputJson AS jsonb), updated_at = now()
         WHERE vat_form_id = CAST(:id AS bigint)
         RETURNING vat_form_id AS "vatFormId", input_values AS "inputValues", confirmed AS "confirmed"`,
        { inputJson, id },
      );
      return rows[0];
    });
  }
}

