import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const SIZE = 20;

function parseJson(text: string): Row {
  const src = text.trim() === '' ? '{}' : text;
  let parsed: unknown;
  try {
    parsed = JSON.parse(src);
  } catch (e) {
    throw new Error('서식 입력값이 올바른 JSON 형식이 아닙니다.');
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error('서식 입력값은 객체 형식이어야 합니다.');
  }
  return parsed as Row;
}

export default function FnSfr01006Page({ role, notify }: PageProps) {
  const [start, setStart] = useState('');
  const [end, setEnd] = useState('');
  const [formType, setFormType] = useState('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [cStart, setCStart] = useState('');
  const [cEnd, setCEnd] = useState('');
  const [cType, setCType] = useState('');
  const [cInput, setCInput] = useState('');
  const [eInput, setEInput] = useState('');

  const { data, error, reload } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/vat-forms', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page, role]);

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const confirmedCount = rows.filter((r) => r['confirmed'] === true).length;

  function search() {
    if (!start || !end || !formType.trim()) {
      notify('과세기간과 서식 구분을 모두 입력해 주세요.');
      return;
    }
    if (!DATE_RE.test(start) || !DATE_RE.test(end) || end < start) {
      notify('과세기간이 올바르지 않습니다.');
      return;
    }
    setPage(0);
    setApplied({ taxPeriodStart: start, taxPeriodEnd: end, formType: formType.trim() });
  }

  function reset() {
    setStart('');
    setEnd('');
    setFormType('');
    setApplied(null);
    setPage(0);
  }

  function openCreate() {
    setCStart(start);
    setCEnd(end);
    setCType(formType);
    setCInput('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setEInput(JSON.stringify(row['inputValues'] ?? {}, null, 2));
    setEditing(row);
  }

  async function create() {
    if (!cStart || !cEnd || !cType.trim()) {
      throw new Error('과세기간과 서식 구분을 모두 입력해 주세요.');
    }
    const inputValues = parseJson(cInput);
    await call('POST', '/vat-forms', role, {
      taxPeriodStart: cStart,
      taxPeriodEnd: cEnd,
      formType: cType.trim(),
      inputValues,
    });
    notify('부가가치세 서식을 저장했습니다.');
    setCreating(false);
    setStart(cStart);
    setEnd(cEnd);
    setFormType(cType.trim());
    setPage(0);
    setApplied({ taxPeriodStart: cStart, taxPeriodEnd: cEnd, formType: cType.trim() });
    reload();
  }

  async function update() {
    if (!editing) {
      return;
    }
    const inputValues = parseJson(eInput);
    await call('PATCH', '/vat-forms/' + String(editing['vatFormId']), role, { inputValues });
    notify('서식 입력값을 수정했습니다.');
    setEditing(null);
    setDetail(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회된 서식', total],
            ['확정 서식', confirmedCount],
            ['수정 가능 서식', rows.length - confirmedCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>부가가치세 서식</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="과세기간 시작일" required>
            <DateInput value={start} onChange={setStart} />
          </Field>
          <Field label="과세기간 종료일" required>
            <DateInput value={end} onChange={setEnd} />
          </Field>
          <Field label="서식 구분" required>
            <TextInput value={formType} onChange={setFormType} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>서식 등록</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          rows={rows}
          empty={applied ? '조회된 서식이 없습니다.' : '과세기간과 서식 구분을 입력하고 조회해 주세요.'}
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'vatFormId', label: '부가가치세 서식 ID' },
            { key: 'taxPeriodStart', label: '과세기간 시작일', render: (r) => <DateText value={r['taxPeriodStart']} /> },
            { key: 'taxPeriodEnd', label: '과세기간 종료일', render: (r) => <DateText value={r['taxPeriodEnd']} /> },
            { key: 'formType', label: '서식 구분' },
            { key: 'confirmed', label: '확정 여부', render: (r) => <Badge value={r['confirmed'] === true ? '확정' : '미확정'} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                r['confirmed'] === true ? null : (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      openEdit(r);
                    }}
                  >
                    수정
                  </button>
                ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="부가가치세 서식 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['부가가치세 서식 ID', String(detail['vatFormId'])],
              ['과세기간 시작일', <DateText value={detail['taxPeriodStart']} />],
              ['과세기간 종료일', <DateText value={detail['taxPeriodEnd']} />],
              ['서식 구분', String(detail['formType'])],
              ['확정 여부', <Badge value={detail['confirmed'] === true ? '확정' : '미확정'} />],
              ['서식 입력값', <pre>{JSON.stringify(detail['inputValues'] ?? {}, null, 2)}</pre>],
            ]}
          />
          {detail['confirmed'] === true ? null : (
            <button
              type="button"
              onClick={() => {
                openEdit(detail);
                setDetail(null);
              }}
            >
              입력값 수정
            </button>
          )}
        </Drawer>
      ) : null}
      {creating ? (
        <Drawer title="부가가치세 서식 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="저장">
            <Field label="과세기간 시작일" required>
              <DateInput value={cStart} onChange={setCStart} />
            </Field>
            <Field label="과세기간 종료일" required>
              <DateInput value={cEnd} onChange={setCEnd} />
            </Field>
            <Field label="서식 구분" required>
              <TextInput value={cType} onChange={setCType} />
            </Field>
            <Field label="서식 입력값" wide hint="JSON 객체 형식">
              <TextInput value={cInput} onChange={setCInput} multiline placeholder="{}" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {editing ? (
        <Drawer title="서식 입력값 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={update} submit="수정 저장">
            <Field label="서식 입력값" required wide hint="JSON 객체 형식">
              <TextInput value={eInput} onChange={setEInput} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
